  header();for(const row of rows){const cells=row.map((v,i)=>wrap(v,widths[i]-5,size));let offset=0,total=Math.max(...cells.map(c=>c.length));while(offset<total){const lh=size*.46,capacity=Math.floor((bottom-y-6)/lh);if(capacity<2||(m.consolidated&&m.departmentResponse&&bottom-y<20)){page();header();continue;}const take=Math.min(total-offset,capacity),height=Math.max(take*lh+6,m.consolidated&&m.departmentResponse?20:0);let x=left;cells.forEach((lines,i)=>{rect(x,y,widths[i],height);font(size);const part=m.consolidated&&i===0&&offset>0?wrap(row[0],widths[0]-5,size):lines.slice(offset,offset+take);if(part.length)pdf.text(part,x+2.5,y+4.5,{lineHeightFactor:1.3});x+=widths[i];});y+=height;offset+=take;if(offset<total){page();header();}}}y+=7;
